from lib import *
S = SS('j275')
steps = [
    step("脏检查(Hibernate ORM 6.6.4 + 真实 PostgreSQL 16.15):用 find 加载 P(1) 发出 1 条 SELECT,em.contains(p) = true;之后 p.age = 31——没有调用任何 save / update / persist——commit 时发出 update P set age=?,name=? where id=?(即使只改了 age,默认 UPDATE 也包含所有列)。把 age 赋成相同的值再 commit,0 条 UPDATE;改成 99 又改回原值,也是 0 条(与加载时的快照比较,中间状态无关)。批量更新绕过持久化上下文:JPQL update P set age = 70 影响 1 行,但内存里的 p.age 仍是 40,em.refresh(p) 之后才是 70。", t=tl(S(1)), done=lidx(S(1), 'find 之后:SQL 语句数 +1', 'p.age = 31', 'update P set age=?,name=? where id=?'), mark=lidx(S(1), '把 age 赋成相同的值', '改成 99 又改回原值', '批量更新绕过持久化上下文', 'update P p1_0 set age=70', 'refresh'), kv=KV([['改字段后 commit', '自动发出 update(所有列)'], ['赋相同值 / 改了又改回', '0 条 UPDATE'], ['JPQL 批量更新', '内存里仍是旧值,refresh 才更新']], ['改字段后 commit'])),
    step("一级缓存与身份映射:同一个 EntityManager 里 find 两次同一个主键,x1 == x2 为 true,只发 1 条 SQL;用 JPQL 再查同一行仍然发 SQL(语句数 +2),但返回的对象 == x1 为 true;另一个 EntityManager 里 find 同一行得到的对象与 x1 不是同一个(y == x1 为 false,没有重写 equals 时 y.equals(x1) 也是 false)。getReference(2) 不发 SQL,返回 Hibernate 生成的代理子类对象,isInitialized = false;直接读它的字段 ref.name 是 null(代理自己的字段,没有触发加载);调用 ref.getName() 才发 1 条 SQL 并得到 bob。", t=tl(S(2)), done=lidx(S(2), 'find 两次', 'JPQL 查同一行', '另一个 EntityManager'), mark=lidx(S(2), 'getReference(2)', '直接读代理对象的字段', 'ref.getName()'), kv=KV([['同一个 EntityManager', 'find 两次是同一个对象,只发 1 条 SQL'], ['另一个 EntityManager', '得到不同的对象'], ['getReference 代理', '读字段得到 null,调用 getter 才加载']], ['getReference 代理'])),
    step("托管、游离与 merge:find 之后 detach,再改 age = 500 并 commit:0 条 UPDATE(游离对象的修改不会被保存),contains = false;把游离对象交给 merge:先发 1 条 SELECT 加载托管副本,返回的 merged 与 d 不是同一个对象(merged 托管,d 仍然游离),merged.age = 500,commit 发 1 条 UPDATE;之后再改 d.age 没有任何效果。新建的 P:persist 之前 id = null,persist 之后立刻发 insert 并得到 id = 3(IDENTITY 策略需要立刻 INSERT 才拿到 id),contains = true。", t=tl(S(3)), done=lidx(S(3), 'detach 之后改 age = 500', '把游离对象 d 交给 merge'), mark=lidx(S(3), 'update P set age=?,name=? where id=?', 'persist 前 id = null', 'insert into P'), kv=KV([['detach 之后的修改', '不保存(0 条 UPDATE)'], ['merge(d)', '返回新的托管对象,d 仍然游离'], ['persist(IDENTITY)', '立刻 INSERT 以获得 id']], ['merge(d)'])),
    step("flush 的时机:改了 bob 的 age = 71 之后立刻 JPQL 查询 count(age = 71)。FlushMode = AUTO:先发 update 再发 select count,结果是 1(查询新增 2 条 SQL);FlushMode = COMMIT:只发 select count,结果是 0——查询看不到还没 flush 的修改(查询新增 1 条 SQL)。AUTO 让查询总能看见自己的修改,代价是查询之前可能多出一次写。", t=tl(S(4)), done=lidx(S(4), 'FlushMode = AUTO', 'select count(p1_0.id)'), mark=lidx(S(4), 'FlushMode = COMMIT'), b=bars([['AUTO:count 结果', 1, '1(先 UPDATE 再 SELECT)'], ['COMMIT:count 结果', 0, '0(只有 SELECT)']], 1, done=[0, 1]), kv=KV([['AUTO', '查询前先 flush,count = 1,2 条 SQL'], ['COMMIT', '不 flush,count = 0,1 条 SQL']], ['AUTO'])),
    step("代价:每次 flush 都要对所有托管实体做脏检查。没有任何修改时 flush 的耗时(31 次中位数,第二轮):1000 个托管实体 0.08 ms,10000 个 0.71 ms,50000 个 3.70 ms;改其中 1 个后 flush 分别是 1.19、1.13、4.82 ms;em.clear() 之后 flush 只要 0.003 / 0.002 / 0.005 ms。以只读方式加载 50000 个实体(hint org.hibernate.readOnly = true)flush 约 2.87 ms(依然遍历),而被修改后 flush 不发任何 SQL(只读实体的修改不会写回)。大批量读取后应 em.clear() 或用只读查询。", t=tl(S(5)), done=lidx(S(5), '1000 个托管实体', '10000 个托管实体'), mark=lidx(S(5), '50000 个托管实体', 'readOnly', '只读加载的实体被修改后'), b=bars([['1000 个:无修改 flush', 0.08, '0.08 ms'], ['10000 个', 0.71, '0.71 ms'], ['50000 个', 3.70, '3.70 ms'], ['50000 个 + clear()', 0.005, '0.005 ms']], 3.7, done=[0, 1, 2, 3]), kv=KV([['脏检查成本', '随托管实体数线性增长:0.08 → 0.71 → 3.70 ms'], ['em.clear()', 'flush 降到 0.003–0.005 ms']], ['脏检查成本'])),
]
A = mkartj('j275', 275, 'Java,JPA,Hibernate,持久化上下文,脏检查,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测持久化上下文:改托管实体的字段不用调用任何 save 就会在 commit 时发出(包含所有列的)UPDATE;同一 EntityManager 里同一主键是同一个对象;detach 后的修改不保存、merge 返回新的托管对象;AUTO 模式下查询前先 flush;托管实体 5 万个时无修改的 flush 也要 3.7 ms。',
    'JPA 里“改了对象就自动保存”不是魔法,而是持久化上下文的脏检查。这篇用真实的 SQL 日志与计时量出:它什么时候发 UPDATE、什么时候不发,一级缓存的身份映射,游离对象与 merge,flush 的时机,以及托管实体变多之后的代价。',
    [('0 条 / 1 条', '托管实体改成相同的值或改了又改回原值 commit 时的 UPDATE 数 / 真正改了值的 UPDATE 数'), ('0.08 → 3.70 ms', '没有任何修改时 flush 的耗时:1000 个托管实体 vs 50000 个'), ('0.005 ms', '50000 个实体加载后 em.clear() 再 flush 的耗时')],
    [('脏检查', None), ('一级缓存与身份映射', None), ('托管、游离与 merge', None), ('flush 时机', None), ('托管实体的代价', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 Homebrew PostgreSQL 16.15(端口 9501),主键策略 IDENTITY,hbm2ddl = create-drop;SQL 来自 hibernate.show_sql,语句计数来自 Hibernate Statistics', '没有验证:Spring Data JPA / @Transactional 的事务边界与 OpenEntityManagerInView、@DynamicUpdate、字节码增强(enhancement)后的脏检查、StatelessSession、乐观锁 / 二级缓存对 flush 的影响、其它 JPA 实现(EclipseLink)'], '持久化上下文')
